            //
            aOrbiterE = ((aOrbiterE + aOrbiterA) + 0xB1DE60F434E14C41ULL) + aPhaseCOrbiterUpdateSaltB[(((31U - aIndex) + 14U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterE) ^ 0x448C0A9EA981C48EULL;
