            aOrbiterD = ((aOrbiterD ^ aOrbiterA) ^ 0x1B28BC6C76CCCC70ULL) ^ aPhaseCOrbiterUpdateSaltC[(((31U - aIndex) + 7U)) & S_SALT1];
