            //
            aIngress = (RotL64(aHeartLaneA[((aIndex + 3920U)) & S_BLOCK1], 27U) ^ RotL64(aHeartLaneB[((aIndex + 777U)) & S_BLOCK1], 48U));
            aIngress ^= (RotL64(aSpiritLaneA[((aIndex + 3191U)) & S_BLOCK1], 13U) ^ RotL64(aPoisonLaneB[((aIndex + 7004U)) & S_BLOCK1], 35U));
            aIngress = TwistMix64::DiffuseC(aIngress);
            //
            aCross = (RotL64(aHeartLaneC[((S_BLOCK1 - aIndex + 4797U)) & S_BLOCK1], 6U) ^ RotL64(aHeartLaneD[((S_BLOCK1 - aIndex + 6930U)) & S_BLOCK1], 27U));
