            aCross = TwistMix64::DiffuseA(aCross);
            //
            aScatter = (RotL64(aCross, 21U) ^ RotL64(aIngress, 5U)) ^ (RotL64(aCarry, 39U) + RotL64(aPrevious, 56U));
            aScatter = TwistMix64::DiffuseA(aScatter);
            //
            aOrbiterI = ((aWandererJ + RotL64(aScatter, 29U)) + RotL64(aCarry, 19U)) + 0x8982088532D3C270ULL;
            aOrbiterK = ((aWandererH + RotL64(aCross, 19U)) + RotL64(aCarry, 57U)) + 0x8ACDBC74E1EB28FDULL;
            aOrbiterB = ((aWandererB + RotL64(aPrevious, 13U)) + 0x36AC6F324F9E3C36ULL) + aPhaseDOrbiterAssignSaltD[((aIndex + 25U)) & S_SALT1];
            aOrbiterD = (aWandererA + RotL64(aIngress, 35U)) + 0x762858FD909FBA56ULL;
            aOrbiterC = ((aWandererD + RotL64(aPrevious, 58U)) + 0x359C3C9DD1AB271FULL) + aPhaseDOrbiterAssignSaltB[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterJ = (aWandererF + RotL64(aCross, 47U)) + 0xE4F482121DDE62ABULL;
            aOrbiterF = ((aWandererG + RotL64(aIngress, 3U)) + RotL64(aCarry, 41U)) + 0xEA90B335261424A3ULL;
            //
            aOrbiterI = (aOrbiterI + aOrbiterK) + 0x7D63E8429676022EULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterI) ^ 0x87076A82FE5F971EULL;
            aOrbiterB = RotL64((aOrbiterB * 0x19872669525C99EBULL), 23U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterC) + 0xB6DDBDBE70FBCB78ULL) + aPhaseDOrbiterUpdateSaltD[((aIndex + 5U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterD) ^ 0xF6A64FC0F3B3F792ULL;
            aOrbiterK = RotL64((aOrbiterK * 0xC5CBDDE9697B17AFULL), 5U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterJ) + 0x99F0E61747969668ULL) + aPhaseDOrbiterUpdateSaltE[((aIndex + 9U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterB) ^ 0x4B791369420BA3C4ULL;
            aOrbiterD = RotL64((aOrbiterD * 0xD5C0B0C8A1EE22C5ULL), 51U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterD) + 0x2BDE0C4775F648F5ULL) + aPhaseDOrbiterUpdateSaltA[((aIndex + 6U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterF) ^ 0xB45F972B444BE897ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x4FC6955C7847225FULL), 13U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterF) + 0xEAADA2E1B73204B3ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterK) ^ 0x5A4B8D0D46FEACC3ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x7C543EB3830815A7ULL), 41U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterI) + 0xF9937B3E69830AC4ULL;
