            //
            aOrbiterC = ((aOrbiterC + aOrbiterB) + 0x693EE7D65E17A785ULL) + aPhaseDOrbiterUpdateSaltB[(((31U - aIndex) + 17U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterC) ^ 0x6B485343AC85E025ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x36D37058B79D3BD1ULL), 35U);
            //
            aIngress = aOrbiterK ^ RotL64(aOrbiterC, 46U);
