            //
            aWandererF = aWandererF ^ ((RotL64(aPrevious, 53U) + aOrbiterK) + RotL64(aOrbiterD, 26U));
            aWandererH = aWandererH + (((RotL64(aScatter, 41U) + aOrbiterI) + RotL64(aOrbiterK, 51U)) + RotL64(aCarry, 27U));
